async function train(pattern, ms) {
  const start = sdk.getSkillXp('Defence');
  const endT = Date.now() + ms;
  let attacks=0;
  while (Date.now() < endT) {
    await bot.dismissBlockingUI();
    const st = sdk.getState();
    if (!st?.player) { await sdk.waitForTicks(1); continue; }
    if (st.player.combat.inCombat) { await sdk.waitForTicks(1); continue; }
    const target = st.nearbyNpcs
      .filter(n => pattern.test(n.name))
      .filter(n => n.optionsWithIndex?.some(o => /attack/i.test(o.text)))
      .sort((a,b)=>a.distance-b.distance)[0];
    if (!target) { await sdk.waitForTicks(1); continue; }
    try { const r = await bot.attack(target); attacks++; if(!r.success) console.log(pattern, r.reason, r.message); } catch(e){ console.log('err',e.message);}
    await sdk.waitForTicks(1);
  }
  const end = sdk.getSkillXp('Defence');
  console.log(pattern.toString(), 'delta', end-start, 'attacks', attacks, 'raw/min', (end-start)/ms*60000);
}
await bot.walkTo(3202,3204,3);
await train(/rat$/i, 15000);

