    try { await sdk.waitForCondition(s => s !== null, 10000); } catch (e) { console.log('no state', e.message); }
    console.log('stateAge', sdk.getStateAge(), 'pos', sdk.getState()?.player?.worldX, sdk.getState()?.player?.worldZ);
    for (let i = 0; i < 5; i++) {
        await bot.dismissBlockingUI();
        await sdk.waitForTicks(2);
        console.log('after dismiss', i, 'stateAge', sdk.getStateAge(), 'dialog', sdk.getState()?.dialog?.isOpen);
    }
    return { stateAge: sdk.getStateAge() };
}, {
    timeout: 25000,
    disconnectAfter: false,
    printState: false,
    onDisconnect: 'wait',
    reconnectTimeout: 15000,
});

