  const range = sdk.findNearbyLoc(/^range$/i);
  if (!item || !range) break;
  const rawBefore = sdk.getInventory().filter(x=>/^raw chicken$/i.test(x.name)).length;
  await bot.useItemOnLoc(item, range);
  await sdk.waitForCondition(state => (state.inventory||[]).filter(x=>/^raw chicken$/i.test(x.name)).length < rawBefore, 1000).catch(()=>{});
